package app.blocker;
import android.app.Activity;import android.os.*;import android.provider.Settings;import android.view.*;import org.json.JSONObject;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.ActivityController;import org.robolectric.util.ReflectionHelpers;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class HoldTouchTest {
 ActivityController<Activity> controller;AlpineScreen view;
 @Before public void setup()throws Exception{controller=Robolectric.buildActivity(Activity.class).setup().visible().windowFocusChanged(true);Activity a=controller.get();Settings.Global.putInt(a.getContentResolver(),Settings.Global.BOOT_COUNT,9);Shadows.shadowOf(a.getSystemService(PowerManager.class)).setIsInteractive(true);State.prefs(a).edit().clear().putInt("boot",9).putBoolean("active",true).putLong("sessionEnd",SystemClock.elapsedRealtime()+3600000).commit();view=new AlpineScreen(a,ignored->{},()->{},()->fail("Early touch must never unlock"));a.setContentView(view);view.update(new JSONObject().put("active",true).put("holdDuration",300000));controller.windowFocusChanged(true);view.measure(View.MeasureSpec.makeMeasureSpec(400,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(800,View.MeasureSpec.EXACTLY));view.layout(0,0,400,800);
  // Robolectric’s WebView provider does not lay out a native browser surface.
  // Supply its pixel frame, then exercise the production touch handler unchanged.
  ReflectionHelpers.setField(view,"mLeft",0);ReflectionHelpers.setField(view,"mTop",0);ReflectionHelpers.setField(view,"mRight",400);ReflectionHelpers.setField(view,"mBottom",800);assertEquals(400,view.getWidth());assertEquals(800,view.getHeight());
  ReflectionHelpers.setField(view,"left",.25);ReflectionHelpers.setField(view,"right",.75);ReflectionHelpers.setField(view,"top",.375);ReflectionHelpers.setField(view,"bottom",.625);assertTrue(view.hasWindowFocus());assertTrue(view.isShown());assertTrue(State.active(a));}
 @After public void close(){view.cancelHold();controller.pause().stop().destroy();view.destroy();}
 private void touch(int action,float x,float y){MotionEvent e=MotionEvent.obtain(0,0,action,x,y,0);view.onTouchEvent(e);e.recycle();}
 @Test public void leavingCancels(){touch(MotionEvent.ACTION_DOWN,200,400);assertTrue(view.holding());assertTrue(view.getKeepScreenOn());touch(MotionEvent.ACTION_MOVE,90,400);assertFalse(view.holding());assertFalse(view.getKeepScreenOn());assertEquals(-1,view.holdLeft());}
 @Test public void liftingResets(){touch(MotionEvent.ACTION_DOWN,200,400);assertTrue(view.holding());touch(MotionEvent.ACTION_UP,200,400);assertFalse(view.holding());touch(MotionEvent.ACTION_DOWN,200,400);assertEquals(300000,view.holdLeft());}
 @Test public void focusLossCancels(){touch(MotionEvent.ACTION_DOWN,200,400);assertTrue(view.holding());view.onWindowFocusChanged(false);assertFalse(view.holding());assertFalse(view.getKeepScreenOn());}
 @Test public void secondFingerCancels(){touch(MotionEvent.ACTION_DOWN,200,400);assertTrue(view.holding());MotionEvent.PointerProperties p0=new MotionEvent.PointerProperties(),p1=new MotionEvent.PointerProperties();p0.id=0;p1.id=1;MotionEvent.PointerCoords c0=new MotionEvent.PointerCoords(),c1=new MotionEvent.PointerCoords();c0.x=c1.x=200;c0.y=c1.y=400;MotionEvent e=MotionEvent.obtain(0,0,MotionEvent.ACTION_POINTER_DOWN|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),2,new MotionEvent.PointerProperties[]{p0,p1},new MotionEvent.PointerCoords[]{c0,c1},0,0,1,1,0,0,0,0);view.onTouchEvent(e);e.recycle();assertFalse(view.holding());assertFalse(view.getKeepScreenOn());}
}
